class Solution {
    public int[] productExceptSelf(int[] nums) {
        int[] answer = new int[nums.length];
        for (int index = 0; index < nums.length; index++) {
            int product = 1;
            for (int other = 0; other < nums.length; other++) {
                if (other != index) product *= nums[other];
            }
            answer[index] = product;
        }
        return answer;
    }
}

