class Solution {
    public int[] productExceptSelf(int[] nums) {
        int[] answer = new int[nums.length];
        int prefix = 1;
        for (int index = 0; index < nums.length; index++) {
            answer[index] = prefix;
            prefix *= nums[index];
        }
        int suffix = 1;
        for (int index = nums.length - 1; index >= 0; index--) {
            answer[index] *= suffix;
            suffix *= nums[index];
        }
        return answer;
    }
}
